var _c = kit.split('{{sel}}', 'chars');
timeline.fromTo(_c, {opacity:0, y:'0.5em'},
  {opacity:1, y:0, duration:{{dur}}, ease:'power3.out', stagger:{{stagger}}}, {{at}});

var _w = kit.split('{{sel}}', 'words');
timeline.fromTo(_w, {opacity:0, filter:'blur(10px)', y:50},
  {opacity:1, filter:'blur(0px)', y:0, duration:{{dur}}, ease:'power2.out', stagger:{{stagger}}}, {{at}});

var _c = kit.split('{{sel}}', 'chars');
timeline.fromTo(_c, {opacity:0, rotationX:92, transformOrigin:'50% 0%', transformPerspective:700},
  {opacity:1, rotationX:0, duration:{{dur}}, ease:'power3.out', stagger:{{stagger}}}, {{at}});

var _t = document.querySelector('{{sel}}');
_t.style.webkitTextStroke = '1.4px currentColor';
_t.style.color = 'transparent';
timeline.to(_t, {color:'{{color}}', duration:0.4, ease:'power1.out'}, {{at}}+{{dur}});

var _t = document.querySelector('{{sel}}');
var _txt = _t.textContent; _t.textContent = '';
for (var i = 1; i <= _txt.length; i++) {
  timeline.set(_t, {textContent: _txt.slice(0, i)}, {{at}} + i*0.05);
}

var _n = document.querySelector('{{sel}}');
var _o = {v:0};
timeline.to(_o, {v:{{n}}, duration:{{dur}}, ease:'power2.out',
  onUpdate: function(){ _n.textContent = Math.round(_o.v); }}, {{at}});

/* 固定种子，渲染可复现 */
var _r = kit.seeded(7), _t = document.querySelector('{{sel}}');
var _final = _t.textContent, _sp = ':.'; _t.textContent = '';
for (var i = 0; i < _final.length; i++) {
  (function (idx) {
    timeline.set(_t, {textContent: _final.slice(0, idx) + _sp[(idx + 1) % _sp.length]}, {{at}} + idx * 0.03);
    timeline.set(_t, {textContent: _final.slice(0, idx + 1)}, {{at}} + idx * 0.03 + 0.09);
  })(i);
}
timeline.set(_t, {textContent: _final}, {{at}} + _final.length * 0.03);

var _r = kit.seeded(11), _t = document.querySelector('{{sel}}');
var _final = _t.textContent, _c = 'ABCDEF0123';
for (var i = 0; i < _final.length; i++) {
  (function (idx) {
    timeline.set(_t, {textContent: _final.slice(0, idx) + _c[Math.floor(_r() * _c.length)]}, {{at}} + idx * 0.04);
    timeline.set(_t, {textContent: _final.slice(0, idx + 1)}, {{at}} + idx * 0.04 + 0.08);
  })(i);
}

/* 每字上下两片，rotationX 由 -90 收敛到 0，翻 3 次落定 */
var _c = kit.split('{{sel}}', 'chars');
_c.forEach(function (el, i) {
  el.style.transformStyle = 'preserve-3d';
  timeline.fromTo(el, {rotationX: -90, opacity: 0},
    {rotationX: 0, opacity: 1, duration: {{dur}}, ease: 'back.out(1.4)'}, {{at}} + i * 0.06);
});

/* 单次沿弧线摆位，不循环 */
var _c = kit.split('{{sel}}', 'chars');
var _n = _c.length;
_c.forEach(function (el, i) {
  var a = (-60 + (120 / Math.max(1, _n - 1)) * i) * Math.PI / 180;
  timeline.fromTo(el,
    {x: 0, y: 0, rotation: a * 57.3, opacity: 0},
    {x: Math.sin(a) * 420, y: (1 - Math.cos(a)) * 420, opacity: 1,
     duration: {{dur}}, ease: 'power2.out'}, {{at}} + i * 0.05);
});

var _c = kit.split('{{sel}}', 'chars');
for (var i = 0; i < 8; i++) {
  timeline.fromTo(_c, {opacity:0, x:i*36, filter:'blur(3px)'},
    {opacity:0.35*(1-i/8), x:0, filter:'blur(0px)', duration:0.5, ease:'power2.out', stagger:0.03},
    {{at}} + i*0.04);
}

var _p = kit.pointer(inner);
timeline.to(_p.pos, {x:0.62, y:0.34, duration:1.0, ease:'power2.inOut'}, {{at}});
timeline.eventCallback('onUpdate', _p.apply);

timeline.eventCallback('onUpdate', function(){
  inner.style.setProperty('--ry', ((_p.pos.x-0.5)*7)+'deg');
  inner.style.setProperty('--rx', ((0.5-_p.pos.y)*5)+'deg');
});
